using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using Demo6.Game;using Demo6.Core.Loot;using Demo6.Core.Combat;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
public static class StyleV4EncounterCheck {
 const string Root="검증/비주얼-개선-v4/after";const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 public static async Task<object> Run(){if(!EditorApplication.isPlaying||DungeonUi.ModalOpen)throw new Exception("Unblocked disposable Play required");var p=PlayerController.Instance;var inv=Inventory.Instance;Vector2 original=p.Position;var originalKb=Keyboard.current;var originalMouse=Mouse.current;var kb=InputSystem.AddDevice<Keyboard>("V4EncounterKeyboard");var mouse=InputSystem.AddDevice<Mouse>("V4EncounterMouse");bool ke=true,me=true,bg=Application.runInBackground,paused=TimeScaleService.Paused;var camera=Camera.main;var follow=camera.GetComponent<DungeonCamera>();var records=new List<object>();
  var a=typeof(Editor).Assembly;var type=a.GetType("UnityEditor.GameView");var view=Resources.FindObjectsOfTypeAll(type).Cast<EditorWindow>().First();var selected=type.GetProperty("selectedSizeIndex",F);int originalIndex=(int)selected.GetValue(view);var sizes=a.GetType("UnityEditor.GameViewSizes");var instance=typeof(ScriptableSingleton<>).MakeGenericType(sizes).GetProperty("instance").GetValue(null);var group=sizes.GetMethod("GetGroup").Invoke(instance,new object[]{GameViewSizeGroupType.Standalone});var sizeType=a.GetType("UnityEditor.GameViewSize");var enumType=a.GetType("UnityEditor.GameViewSizeType");var added=new List<object>();var drops=new List<LootDrop>();
  async Task Shot(string name,int delay=200){ScreenCapture.CaptureScreenshot(Path.GetFullPath(Root+"/"+Screen.height+"-"+name+".png"));await Task.Delay(delay);}
